import type { GameId, Offer } from '../engine/index.ts';
import { interpolateReturn, meterFromRoyalPerCoin, royalPerCoinFromMeter, type ProgressiveCurve } from '../engine/progressive.ts';

/**
 * Exact return vs royal for games offered with a progressive royal (D35), generated by `npm run progressive`
 * into src/progressive/curves.json. Never compute or edit these in the UI.
 */
const modules = import.meta.glob('../progressive/curves.json', { eager: true }) as Record<
  string,
  { default: { games: Partial<Record<GameId, ProgressiveCurve>> } }
>;

export const PROGRESSIVE_CURVES: Partial<Record<GameId, ProgressiveCurve>> = Object.values(modules)[0]?.default.games ?? {};

/** Perfect-play return when the offer's meter shows `dollars` (perfect play re-solved for that royal). */
export function returnAtMeter(gameId: GameId, offer: Offer, dollars: number): number | undefined {
  const curve = PROGRESSIVE_CURVES[gameId];
  return curve && interpolateReturn(curve, royalPerCoinFromMeter(dollars, offer.denomination, offer.maxCoins));
}

/** The meter (dollars, max-bet royal) at which the offer returns 100% with perfect play. */
export function breakEvenMeter(gameId: GameId, offer: Offer): number | undefined {
  const curve = PROGRESSIVE_CURVES[gameId];
  return curve && meterFromRoyalPerCoin(curve.breakEvenRoyal, offer.denomination, offer.maxCoins);
}
